#!/usr/bin/env python3
"""Generates pairing_vectors.json and pow_vectors.json (PLAN_V4 §13).

Independent reference: Python's hashlib/base64 compute codes, hashes and PoW nonces; URL and
normalisation cases are hand-written expectations. Rust (buddy-core) and TypeScript
(src/lib/pairing.ts) must both pass the generated files.

    python3 gen_account_vectors.py   # writes both files next to this script
"""
import base64
import hashlib
import json
import os

ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
HERE = os.path.dirname(os.path.abspath(__file__))


def crockford(data: bytes, length: int) -> str:
    bits = "".join(f"{b:08b}" for b in data)
    return "".join(ALPHABET[int(bits[i * 5:i * 5 + 5], 2)] for i in range(length))


def group4(code: str) -> str:
    return "-".join(code[i:i + 4] for i in range(0, len(code), 4))


def sha256_hex(s: str) -> str:
    return hashlib.sha256(s.encode()).hexdigest()


def seeded(label: str, n: int) -> bytes:
    return hashlib.sha256(label.encode()).digest()[:n]


def code_case(data: bytes, length: int) -> dict:
    code = crockford(data, length)
    return {"bytes": data.hex(), "code": code, "formatted": group4(code), "hash": sha256_hex(code)}


pairing_bytes = [bytes(8), bytes([0xFF] * 8), bytes.fromhex("0123456789abcdef")] + [
    seeded(f"pairing-{i}", 8) for i in range(5)
]
recovery_bytes = [bytes(15), bytes([0xFF] * 15)] + [seeded(f"recovery-{i}", 15) for i in range(4)]

C = "ABCDEFGHJKMN"
pairing = {
    "$comment": "Generated by gen_account_vectors.py. Pairing codes: 12 Crockford-Base32 chars "
    "(first 60 bits of 8 bytes); recovery codes: 24 chars (120 bits). hash = SHA-256 hex of the "
    "normalised code. urls: origin/code null = not a Display Buddy pairing URL.",
    "codes": [code_case(b, 12) for b in pairing_bytes],
    "normalize": [
        {"input": "ABCDEFGHJKMN", "code": C},
        {"input": "abcd-efgh-jkmn", "code": C},
        {"input": "  ABCD EFGH JKMN \n", "code": C},
        {"input": "abcd--efgh  jkmn", "code": C},
        {"input": "OOOO-IIII-LLLL", "code": "000011111111"},
        {"input": "oil0-1234-5678", "code": "011012345678"},
        {"input": "ABCD-EFGH-JKM", "code": None},
        {"input": "ABCD-EFGH-JKMNP", "code": None},
        {"input": "ABCD-EFGH-JKMU", "code": None},
        {"input": "ABCD_EFGH_JKMN", "code": None},
        {"input": "ABCD.EFGH.JKMN", "code": None},
        {"input": "", "code": None},
        {"input": "ÄBCD-EFGH-JKMN", "code": None},
    ],
    "recovery": [code_case(b, 24) for b in recovery_bytes],
    "recoveryNormalize": [
        {"input": "abcd-efgh-jkmn-pqrs-tvwx-yz01", "code": "ABCDEFGHJKMNPQRSTVWXYZ01"},
        {"input": "ABCD EFGH JKMN PQRS TVWX YZOI", "code": "ABCDEFGHJKMNPQRSTVWXYZ01"},
        {"input": "ABCD-EFGH-JKMN-PQRS-TVWX-YZ0", "code": None},
        {"input": "ABCD-EFGH-JKMN", "code": None},
        {"input": "ABCD-EFGH-JKMN-PQRS-TVWX-YZ0U", "code": None},
    ],
    "urls": [
        {"input": f"https://buddy.pev-point.de/pair#c={C}", "origin": "https://buddy.pev-point.de", "code": C},
        {"input": "https://buddy.pev-point.de/pair#c=abcd-efgh-jkmn", "origin": "https://buddy.pev-point.de", "code": C},
        {"input": f"  https://buddy.pev-point.de/pair#c={C}\n", "origin": "https://buddy.pev-point.de", "code": C},
        {"input": f"HTTPS://Buddy.Pev-Point.DE/pair#c={C}", "origin": "https://buddy.pev-point.de", "code": C},
        {"input": f"https://notes.example.net:8443/pair#c={C}", "origin": "https://notes.example.net:8443", "code": C},
        {"input": f"https://notes.example.net:443/pair#c={C}", "origin": "https://notes.example.net:443", "code": C},
        {"input": f"http://localhost:8080/pair#c={C}", "origin": "http://localhost:8080", "code": C},
        {"input": f"http://127.0.0.1/pair#c={C}", "origin": "http://127.0.0.1", "code": C},
        {"input": f"http://[::1]:8080/pair#c={C}", "origin": "http://[::1]:8080", "code": C},
        {"input": f"http://10.0.2.2:8080/pair#c={C}", "origin": "http://10.0.2.2:8080", "code": C},
        {"input": f"https://[2001:db8::1]/pair#c={C}", "origin": "https://[2001:db8::1]", "code": C},
        {"input": f"https://xn--bddy-0ra.example/pair#c={C}", "origin": "https://xn--bddy-0ra.example", "code": C},
        {"input": f"http://buddy.pev-point.de/pair#c={C}", "origin": None, "code": None},
        {"input": f"http://192.168.1.10:8080/pair#c={C}", "origin": None, "code": None},
        {"input": f"ftp://buddy.pev-point.de/pair#c={C}", "origin": None, "code": None},
        {"input": f"buddy.pev-point.de/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/login#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pair/#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/sub/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pairing#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pair?c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pair?x=1#c={C}", "origin": None, "code": None},
        {"input": "https://buddy.pev-point.de/pair", "origin": None, "code": None},
        {"input": "https://buddy.pev-point.de/pair#", "origin": None, "code": None},
        {"input": "https://buddy.pev-point.de/pair#c=", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pair#code={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pair#c={C}&k=secret", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de/pair#x=1&c={C}", "origin": None, "code": None},
        {"input": "https://buddy.pev-point.de/pair#c=ABCD-EFGH-JKMU", "origin": None, "code": None},
        {"input": f"https://user@buddy.pev-point.de/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://user:pw@buddy.pev-point.de/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://büddy.example/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de:/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy.pev-point.de:99999/pair#c={C}", "origin": None, "code": None},
        {"input": f"https://buddy_x.example/pair#c={C}", "origin": None, "code": None},
        {"input": f"https:///pair#c={C}", "origin": None, "code": None},
        {"input": C, "origin": None, "code": None},
        {"input": "", "origin": None, "code": None},
    ],
    "build": [
        {"origin": "https://buddy.pev-point.de", "code": C, "url": f"https://buddy.pev-point.de/pair#c={C}"},
        {"origin": "http://localhost:8080", "code": "000011111111", "url": "http://localhost:8080/pair#c=000011111111"},
    ],
}


def b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode().rstrip("=")


def zero_bits(h: bytes) -> int:
    n = 0
    for b in h:
        if b == 0:
            n += 8
            continue
        return n + (8 - b.bit_length())
    return n


def digest(ch: bytes, nonce: int) -> bytes:
    return hashlib.sha256(ch + nonce.to_bytes(4, "little")).digest()


pow_cases = []
for i, bits in enumerate([0, 1, 4, 8, 12, 16]):
    ch = seeded(f"challenge-{i}", 16)
    first = next(n for n in range(1 << 32) if zero_bits(digest(ch, n)) >= bits)
    invalid = []
    if bits > 0:  # with 0 bits every nonce is valid
        invalid = [n for n in range(first) if zero_bits(digest(ch, n)) < bits][-3:]
        invalid.append(next(n for n in range(first + 1, 1 << 32) if zero_bits(digest(ch, n)) < bits))
    pow_cases.append({
        "challenge": b64url(ch),
        "bits": bits,
        "digestNonce0": digest(ch, 0).hex(),
        "firstNonce": first,
        "invalidNonces": invalid,
    })

pow_vectors = {
    "$comment": "Generated by gen_account_vectors.py. SHA-256(challenge_bytes || nonce_u32_le) must "
    "start with >= bits zero bits; firstNonce = smallest solution from 0; challenge = base64url "
    "without padding.",
    "cases": pow_cases,
    "malformedChallenges": ["", "not base64!", "AAAA=", "+/+/"],
}

for name, data in [("pairing_vectors.json", pairing), ("pow_vectors.json", pow_vectors)]:
    with open(os.path.join(HERE, name), "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print("wrote", name)
